t v=useContext(SaaSContext);if(!v)throw new Error("useSaaS must be inside SaaSProvider");return v}\n', 'src/components/SaaSAccessBoundary.jsx': 'import { Navigate, Outlet, useLocation } from "react-router-dom";\nimport { useAuth } from "../context/AuthContext";\nimport { useSaaS } from "../context/SaaSContext";\n\nexport default function SaaSAccessBoundary(){\n  const location=useLocation();\n  const {signOut}=useAuth();\n  const saas=useSaaS();\n\n  if(saas.loading)return <div className="auth-screen"><div className="auth-card">Checking subscription...</div></div>;\n  if(saas.error)return <div className="auth-screen"><div className="auth-card"><h2>Subscription Check Unavailable</h2><p>{saas.error}</p><div className="button-row"><button className="primary-button" onClick={saas.refresh}>Retry</button><button className="secondary-button" onClick={signOut}>Sign Out</button></div></div></div>;\n  if(!saas.allowed)return <div className="auth-screen"><div className="auth-card"><h2>{saas.isDemo?"Demo Trial Expired":"Subscription Expired"}</h2><p>Plan: <strong>{saas.planCode}</strong></p><p>Status: <strong>{saas.subscriptionStatus}</strong></p><p>Contact the software provider to renew or extend access.</p><button className="secondary-button" onClick={signOut}>Sign Out</button></div></div>;\n  if(saas.isDemo&&location.pathname!=="/demo")return <Navigate to="/demo" replace/>;\n  if(!saas.isDemo&&location.pathname==="/demo")return <Navigate to="/" replace/>;\n  return <Outlet/>;\n}\n', 'src/components/RequirePlatformAdmin.jsx': 'import { Navigate, Outlet } from "react-router-dom";\nimport { useSaaS } from "../context/SaaSContext";\nexport default function RequirePlatformAdmin(){const{loading,isPlatformAdmin}=useSaaS();if(loading)return <div className="auth-screen"><div className="auth-card">Checking platform access...</div></div>;return isPlatformAdmin?<Outlet/>:<Navigate to="/" replace/>}\n', 'src/components/SaaSBanner.jsx': 'import { Link } from "react-router-dom";\nimport { useSaaS } from "../context/SaaSContext";\nfunction remaining(iso){if(!iso)return"";const ms=new Date(iso).getTime()-Date.now();if(!Number.isFinite(ms))return"";if(ms<=0)return"expired";const h=Math.ceil(ms/3600000);return h<48?`${h} hour${h===1?"":"s"} left`:`${Math.ceil(h/24)} days left`}\nexport default function SaaSBanner(){\n  const s=useSaaS();const expiry=remaining(s.expiresAt||s.trialEndsAt);const update=s.latestVersion&&s.latestVersion!==s.appVersion;\n  if(!s.announcementMessage&&!update&&!s.isDemo&&!s.isPlatformAdmin)return null;\n  return <div style={{margin:"10px 16px 0",border:"1px solid rgba(148,163,184,.35)",borderRadius:12,padding:"10px 14px",display:"flex",gap:12,alignItems:"center",flexWrap:"wrap"}}>\n    {s.isDemo?<strong>DEMO · 2-day trial {expiry?`· ${expiry}`:""}</strong>:null}\n    {s.announcementMessage?<span><strong>{s.announcementSeverity}:</strong> {s.announcementMessage}</span>:null}\n    {update?<span><strong>New version {s.latestVersion}</strong> {s.updateMessage}</span>:null}\n    {s.isPlatformAdmin?<Link to="/platform-admin" style={{marginLeft:"auto"}}>Platform Control</Link>:null}\n  </div>\n}\n', 'src/pages/DemoWorkspace.jsx': 'import { useMemo, useState } from "react";\nimport { useAuth } from "../context/AuthContext";\nimport { useSaaS } from "../context/SaaSContext";\n\nexport const DEMO_SESSION_KEY="wineshoppos_demo_workspace_v1";\nconst SEED={products:[\n{id:"d1",barcode:"8901234500011",name:"Kingfisher Premium 650 ml",category:"Beer",price:160,stock:48},\n{id:"d2",barcode:"8901234500028",name:"Budweiser Magnum 650 ml",category:"Beer",price:220,stock:36},\n{id:"d3",barcode:"8901234500035",name:"Royal Stag 750 ml",category:"Whisky",price:780,stock:18},\n{id:"d4",barcode:"8901234500042",name:"Blenders Pride 750 ml",category:"Whisky",price:1250,stock:14},\n{id:"d5",barcode:"8901234500059",name:"Old Monk 750 ml",category:"Rum",price:720,stock:21},\n{id:"d6",barcode:"8901234500066",name:"Smirnoff Red 750 ml",category:"Vodka",price:980,stock:17},\n{id:"d7",barcode:"8901234500073",name:"Sula Chenin Blanc 750 ml",category:"Wine",price:900,stock:12},\n{id:"d8",barcode:"8901234500080",name:"Bacardi Carta Blanca 750 ml",category:"Rum",price:1050,stock:10}\n],sales:[{id:"S-1001",at:"Today 10:15",total:440},{id:"S-1002",at:"Today 11:02",total:780},{id:"S-1003",at:"Today 11:44",total:1250}]};\nconst fresh=()=>JSON.parse(JSON.stringify(SEED));\nfunction load(){try{const raw=sessionStorage.getItem(DEMO_SESSION_KEY);return raw?JSON.parse(raw):fresh()}catch{return fresh()}}\nexport function clearDemoWorkspace(){sessionStorage.removeItem(DEMO_SESSION_KEY)}\nexport default function DemoWorkspace(){\n const{signOut}=useAuth();const{trialEndsAt}=useSaaS();const[data,setData]=useState(load);const[msg,setMsg]=useState("Demo data is temporary and never saved to Supabase.");\n function save(next){setData(next);sessionStorage.setItem(DEMO_SESSION_KEY,JSON.stringify(next))}\n function sell(p){if(p.stock<=0)return;save({...data,products:data.products.map(x=>x.id===p.id?{...x,stock:x.stock-1}:x),sales:[{id:`DEMO-${Date.now()}`,at:"Just now",total:p.price},...data.sales]});setMsg(`${p.name} sold in demo memory only.`)}\n function receive(p){save({...data,products:data.products.map(x=>x.id===p.id?{...x,stock:x.stock+12}:x)});setMsg(`Received 1 demo case (+12) of ${p.name}.`)}\n function reset(){clearDemoWorkspace();setData(fresh());setMsg("Demo workspace restored to original seed data.")}\n const revenue=useMemo(()=>data.sales.reduce((s,x)=>s+Number(x.total||0),0),[data.sales]);const units=useMemo(()=>data.products.reduce((s,x)=>s+Number(x.stock||0),0),[data.products]);\n return <div style={{padding:24,maxWidth:1200,margin:"0 auto"}}>\n  <div style={{display:"flex",justifyContent:"space-between",gap:16,flexWrap:"wrap",alignItems:"center"}}><div><h1>WineShopPOS Demo Workspace</h1><p>Disposable browser-only workspace · resets on logout/new session.</p><p><strong>Trial ends:</strong> {trialEndsAt?new Date(trialEndsAt).toLocaleString():"2 days after first demo login"}</p></div><div style={{display:"flex",gap:8}}><button className="secondary-button" onClick={reset}>Reset Demo</button><button className="secondary-button" onClick={signOut}>Logout</button></div></div>\n  <div className="purchase-message" style={{margin:"16px 0"}}>{msg}</div>\n  <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:12,marginBottom:18}}><div className="auth-card"><strong>{data.products.length}</strong><div>Products</div></div><div className="auth-card"><strong>{units}</strong><div>Units in stock</div></div><div className="auth-card"><strong>{data.sales.length}</strong><div>Demo sales</div></div><div className="auth-card"><strong>₹{revenue.toLocaleString("en-IN")}</strong><div>Demo revenue</div></div></div>\n  <div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse"}}><thead><tr><th>Barcode</th><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody>{data.products.map(p=><tr key={p.id} style={{borderTop:"1px solid rgba(148,163,184,.25)"}}><td style={{padding:10}}>{p.barcode}</td><td style={{padding:10}}>{p.name}</td><td style={{padding:10}}>{p.category}</td><td style={{padding:10}}>₹{p.price}</td><td style={{padding:10}}>{p.stock}</td><td style={{padding:10}}><button className="primary-button" onClick={()=>sell(p)}>Demo Sale</button> <button className="secondary-button" onClick={()=>receive(p)}>+1 Case</button></td></tr>)}</tbody></table></div>\n </div>\n}\n', 'src/pages/PlatformAdmin.jsx': 'import { useEffect, useState } from "react";\nimport { supabase } from "../lib/supabase";\nimport { useSaaS } from "../context/SaaSContext";\n\nexport default function PlatformAdmin(){\n const saas=useSaaS();const[accounts,setAccounts]=useState([]);const[msg,setMsg]=useState("");\n const[account,setAccount]=useState({email:"",plan:"BASIC",status:"ACTIVE",expiresAt:"",demo:false,trialDays:2});\n const[runtime,setRuntime]=useState({latest:saas.latestVersion||"V4",minimum:saas.minimumSupportedVersion||"V4",force:false,updateMessage:saas.updateMessage||""});\n const[notice,setNotice]=useState({message:"",severity:"INFO",hours:24});\n async function load(){const{data,error}=await supabase.rpc("saas_admin_list_accounts");if(error)setMsg(error.message);else setAccounts(data||[])}\n useEffect(()=>{void load()},[]);\n async function saveAccount(e){e.preventDefault();const{error}=await supabase.rpc("saas_admin_set_account_by_email",{p_email:account.email.trim(),p_plan_code:account.plan,p_status:account.status,p_expires_at:account.expiresAt?new Date(account.expiresAt).toISOString():null,p_demo:account.demo,p_trial_days:Number(account.trialDays||2)});if(error)setMsg(error.message);else{setMsg(account.demo?"Demo configured. Trial starts on first demo login.":"Subscription updated.");await load()}}\n async function saveRuntime(e){e.preventDefault();const{error}=await supabase.rpc("saas_admin_set_runtime",{p_latest_version:runtime.latest,p_minimum_supported_version:runtime.minimum,p_force_update:runtime.force,p_update_message:runtime.updateMessage});if(error)setMsg(error.message);else{setMsg("Version controls saved.");await saas.refresh()}}\n async function publish(e){e.preventDefault();const{error}=await supabase.rpc("saas_admin_publish_announcement",{p_message:notice.message,p_severity:notice.severity,p_hours:Number(notice.hours||24)});if(error)setMsg(error.message);else{setMsg("Flash message published.");setNotice({...notice,message:""});await saas.refresh()}}\n return <div style={{padding:24,maxWidth:1200,margin:"0 auto"}}><h1>WineShopPOS Platform Control</h1><p>Provider-only subscriptions, trials, version notices and flash messages.</p>{msg?<div className="purchase-message">{msg}</div>:null}\n <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(300px,1fr))",gap:16}}>\n <form className="auth-card" onSubmit={saveAccount}><h2>Account / Subscription</h2><label>Email<input type="email" required value={account.email} onChange={e=>setAccount({...account,email:e.target.value})}/></label><label><input type="checkbox" checked={account.demo} onChange={e=>setAccount({...account,demo:e.target.checked})}/> Disposable demo account</label>{account.demo?<label>Trial days<input type="number" min="1" max="30" value={account.trialDays} onChange={e=>setAccount({...account,trialDays:e.target.value})}/></label>:<><label>Plan<select value={account.plan} onChange={e=>setAccount({...account,plan:e.target.value})}><option>BASIC</option><option>PLUS</option><option>PRO</option><option>ENTERPRISE</option></select></label><label>Status<select value={account.status} onChange={e=>setAccount({...account,status:e.target.value})}><option>ACTIVE</option><option>TRIALING</option><option>PAST_DUE</option><option>SUSPENDED</option><option>EXPIRED</option><option>CANCELLED</option></select></label><label>Expires<input type="datetime-local" value={account.expiresAt} onChange={e=>setAccount({...account,expiresAt:e.target.value})}/></label></>}<button className="primary-button">Save Account</button></form>\n <form className="auth-card" onSubmit={saveRuntime}><h2>Version Control</h2><label>Latest version<input value={runtime.latest} onChange={e=>setRuntime({...runtime,latest:e.target.value})}/></label><label>Minimum supported<input value={runtime.minimum} onChange={e=>setRuntime({...runtime,minimum:e.target.value})}/></label><label><input type="checkbox" checked={runtime.force} onChange={e=>setRuntime({...runtime,force:e.target.checked})}/> Force update notice</label><label>Update message<textarea rows="3" value={runtime.updateMessage} onChange={e=>setRuntime({...runtime,updateMessage:e.target.value})}/></label><button className="primary-button">Save Version Controls</button></form>\n <form className="auth-card" onSubmit={publish}><h2>Flash Message</h2><label>Message<textarea required rows="4" value={notice.message} onChange={e=>setNotice({...notice,message:e.target.value})}/></label><label>Severity<select value={notice.severity} onChange={e=>setNotice({...notice,severity:e.target.value})}><option>INFO</option><option>SUCCESS</option><option>WARNING</option><option>CRITICAL</option></select></label><label>Show hours<input type="number" min="1" max="720" value={notice.hours} onChange={e=>setNotice({...notice,hours:e.target.value})}/></label><button className="primary-button">Publish Flash Message</button></form>\n </div><h2 style={{marginTop:24}}>Accounts</h2><div style={{overflowX:"auto"}}><table style={{width:"100%"}}><thead><tr><th>Email</th><th>Role</th><th>Mode</th><th>Plan</th><th>Status</th><th>Expiry</th></tr></thead><tbody>{accounts.map(a=><tr key={`${a.user_id}-${a.email}`}><td>{a.email}</td><td>{a.role}</td><td>{a.demo?"DEMO":"LIVE"}</td><td>{a.plan_code}</td><td>{a.status}</td><td>{a.expires_at?new Date(a.expires_at).toLocaleString():"No expiry"}</td></tr>)}</tbody></table></div></div>\n}\n'}
